<?php
require __DIR__ . '/includes/admin_bootstrap.php';
$page_title='Messages';$status=(string)($_GET['status']??'');$allowed=['new','read','replied','archived'];$where='';$params=[];if(in_array($status,$allowed,true)){$where=' WHERE status=?';$params[]=$status;}$s=$pdo->prepare("SELECT * FROM contact_messages{$where} ORDER BY created_at DESC");$s->execute($params);$rows=$s->fetchAll();require __DIR__.'/includes/header.php';
?><div class="filter-tabs"><a class="<?= $status===''?'selected':'' ?>" href="messages.php">All</a><?php foreach($allowed as $value): ?><a class="<?= $status===$value?'selected':'' ?>" href="messages.php?status=<?= $value ?>"><?= ucfirst($value) ?></a><?php endforeach; ?></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Subject</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr class="<?= $row['status']==='new'?'unread':'' ?>"><td><strong><?= e($row['name']) ?></strong></td><td><?= e($row['email']) ?></td><td><?= e($row['subject']) ?></td><td><span class="badge <?= e($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= e($row['created_at']) ?></td><td><a class="text-link" href="message.php?id=<?= (int)$row['id'] ?>">View &rarr;</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">No messages found.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php'; ?>
